CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, email_verified_at TEXT, password TEXT NOT NULL, remember_token TEXT, role TEXT DEFAULT 'user', account_status TEXT DEFAULT 'active', trial_started_at TEXT, trial_ends_at TEXT, last_login_at TEXT, avatar TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE studio_projects (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, name TEXT NOT NULL, type TEXT DEFAULT 'video', status TEXT DEFAULT 'draft', aspect_ratio TEXT DEFAULT '16:9', duration_seconds INTEGER, settings TEXT, timeline TEXT, prompt TEXT, language TEXT DEFAULT 'en', quality TEXT DEFAULT 'hd', editor_mode TEXT DEFAULT 'smart', brand_settings TEXT, generation_settings TEXT, last_opened_at TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE ai_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, job_uuid TEXT NOT NULL UNIQUE, user_id INTEGER, project_id INTEGER, job_type TEXT NOT NULL, status TEXT DEFAULT 'queued', worker_id TEXT, progress INTEGER DEFAULT 0, payload TEXT, result TEXT, error_message TEXT, started_at TEXT, completed_at TEXT, priority INTEGER DEFAULT 100, attempts INTEGER DEFAULT 0, engine TEXT, queue_name TEXT DEFAULT 'default', available_at TEXT, claimed_at TEXT, heartbeat_at TEXT, failed_at TEXT, output_path TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE studio_outputs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, project_id INTEGER NOT NULL, ai_job_id INTEGER, output_uuid TEXT NOT NULL UNIQUE, name TEXT NOT NULL, output_type TEXT DEFAULT 'video', format TEXT, status TEXT DEFAULT 'ready', path TEXT, source_path TEXT, size_bytes INTEGER, duration_seconds INTEGER, metadata TEXT, generated_at TEXT, downloaded_at TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE studio_usage_events (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, project_id INTEGER, ai_job_id INTEGER, metric TEXT NOT NULL, quantity INTEGER DEFAULT 1, period_key TEXT NOT NULL, metadata TEXT, created_at TEXT, updated_at TEXT);
CREATE TABLE subscription_plans (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, slug TEXT UNIQUE, price NUMERIC DEFAULT 0, billing_cycle TEXT DEFAULT 'monthly', limits TEXT, features TEXT, is_active INTEGER DEFAULT 1, created_at TEXT, updated_at TEXT);
CREATE TABLE user_subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, subscription_plan_id INTEGER, status TEXT DEFAULT 'trial', billing_cycle TEXT, amount NUMERIC DEFAULT 0, starts_at TEXT, ends_at TEXT, cancelled_at TEXT, metadata TEXT, created_at TEXT, updated_at TEXT);
